// Digest of an auto_explain log: distinct statements by total time, and the full plan of the slowest instances.
import { readFileSync, writeFileSync } from "node:fs";
const [inp, out, title] = process.argv.slice(2);
const lines = readFileSync(inp, "utf8").split("\n");
const ts = /^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d\.\d+ UTC \[\d+\] /;
const entries = [];
let cur = null;
for (const l of lines) {
  if (ts.test(l)) {
    if (cur) entries.push(cur);
    const m = /LOG:  duration: ([\d.]+) ms  plan:$/.exec(l);
    cur = m ? { ms: Number(m[1]), head: l, body: [] } : null;
  } else if (cur) cur.body.push(l);
}
if (cur) entries.push(cur);
for (const e of entries) {
  const qi = e.body.findIndex((b) => b.includes("Query Text:"));
  const q = [];
  for (let i = qi; i >= 0 && i < e.body.length; i++) {
    if (i > qi && /^\s*(\S.*\(cost=|Result|Insert|Update|Delete|Seq Scan|Index|Nested|Hash|Sort|Aggregate|Limit|Merge|Bitmap|Function Scan|CTE|Subquery|LockRows|Unique|Append|WindowAgg|Gather|Materialize|Values Scan|ProjectSet)/.test(e.body[i])) break;
    q.push(e.body[i]);
  }
  e.query = q.join(" ").replace(/^\s*Query Text:\s*/, "").replace(/\s+/g, " ").trim();
  e.key = e.query.slice(0, 160);
}
const groups = new Map();
for (const e of entries) {
  const g = groups.get(e.key) ?? { key: e.key, n: 0, total: 0, max: 0, slowest: null };
  g.n++; g.total += e.ms; if (e.ms >= g.max) { g.max = e.ms; g.slowest = e; }
  groups.set(e.key, g);
}
const byTotal = [...groups.values()].sort((a, b) => b.total - a.total);
const L = [`# ${title}`, "", `Source: \`${inp.split("/").pop()}\` (${entries.length} logged plans, ${groups.size} distinct statements by their first 160 characters). auto_explain with log_analyze, log_buffers, log_timing and log_nested_statements = EXPLAIN (ANALYZE, BUFFERS) of each logged statement. The log covers every session of the database during the pass (the API's createExport requests and the worker rendering the queued exports, plus its scheduled jobs).`, "", "## Distinct statements by total time (top 25)", "", "| # | count | total ms | max ms | statement (first 160 characters) |", "| --- | --- | --- | --- | --- |"];
byTotal.slice(0, 25).forEach((g, i) => L.push(`| ${i + 1} | ${g.n} | ${g.total.toFixed(1)} | ${g.max.toFixed(1)} | \`${g.key.replace(/\|/g, "\\|").replace(/`/g, "'")}\` |`));
L.push("", "## Full plans: the slowest instance of the top 10 statements by total time", "");
byTotal.slice(0, 10).forEach((g, i) => { L.push(`### ${i + 1}. ${g.max.toFixed(1)} ms (slowest of ${g.n})`, "", "```", g.slowest.head, ...g.slowest.body.filter((b) => b.trim() !== ""), "```", ""); });
writeFileSync(out, L.join("\n") + "\n");
console.log(`${entries.length} plans, ${groups.size} distinct; top: ${byTotal.slice(0, 3).map((g) => `${g.n}x ${g.total.toFixed(0)}ms ${g.key.slice(0, 60)}`).join(" | ")}`);
EOF
